mapper.select:
		select * from yh_event_enroll 


			  			AND
			(
				event_name like CONCAT('%',#{eventName},'%' )
			)


			and event_type = #{eventType,jdbcType=INTEGER}


			and start_date <>''


			and ISNULL(start_date)


          and org_code in

              #{item}



		order by public_date desc LIMIT  #{page},#{limit}
